const {createHmac,timingSafeEqual}=require('crypto');
const secret=$env.DESKPILOT_WEBHOOK_SECRET;
if(typeof secret!=='string'||!/^[a-f0-9]{64}$/.test(secret))throw new Error('Configure the DeskPilot signing secret');
const headers=$input.first().json.headers;
const raw=await this.helpers.getBinaryDataBuffer(0,'data');
const timestamp=headers['x-deskpilot-timestamp'];
const signature=headers['x-deskpilot-signature'];
const delivery=headers['x-deskpilot-delivery'];
const reject=()=>[{json:{status:401,response:{accepted:false}}}];
if(raw.length>65536||typeof timestamp!=='string'||!/^\d{10,12}$/.test(timestamp)||Math.abs(Date.now()/1000-Number(timestamp))>300||typeof signature!=='string'||!/^sha256=[a-f0-9]{64}$/.test(signature))return reject();
const expected='sha256='+createHmac('sha256',secret).update(timestamp+'.').update(raw).digest('hex');
if(!timingSafeEqual(Buffer.from(signature),Buffer.from(expected)))return reject();
let event;try{event=JSON.parse(raw.toString('utf8'));}catch{return reject();}
if(!event||typeof event!=='object'||typeof event.id!=='string'||typeof event.event!=='string'||event.event!==headers['x-deskpilot-event']||typeof delivery!=='string'||!/^[a-f0-9-]{36}$/.test(delivery))return reject();
// Validation-only template. Add durable deduplication before any side effects.
return [{json:{status:200,response:{accepted:true},delivery_id:delivery,event}}];
